namespace emon;


public static class Calibtest {
    [Xunit.Fact]
    public static void TestASourceBitsetHasOneClass() {
        emon.Testport.AssertEq(Calib.CalClass(Model.SrText()), 0, "text layer");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrHiddenText()), 0, "hidden text is the text layer's");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrText() | Model.SrInfer()), 0, "text and inferred structure: the text layer's");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrOcr()), 1, "OCR");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrOcr() | Model.SrInfer()), 1, "OCR and inferred structure: OCR's");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrText() | Model.SrOcr()), 2, "both");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrHiddenText() | Model.SrOcr()), 2, "hidden text and OCR: both");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrInfer()), 3, "inferred only");
        emon.Testport.AssertEq(Calib.CalClass(Model.SrStruct()), 3, "the tagged tree only: neither");
        emon.Testport.AssertEq(Calib.CalClass(0), 3, "no source");
    }
    [Xunit.Fact]
    public static void TestTheLedgerHasAKindCodeNoNodeKindHas() {
        emon.Testport.AssertEq(Calib.CalDropped(), 100, "the dropped ledger");
        emon.Testport.AssertThat(Calib.CalDropped() > 26, "above the last node kind");
    }
