    [Xunit.Fact]
    public static void TestAKindWithNoRowGoesThroughAsItIs() {
        // Kind 99 is no node kind and no ledger code: no fit has a row for it.
        emon.Testport.AssertEq(Calib.CalConf(99, Model.SrText(), 123), 123, "123");
        emon.Testport.AssertEq(Calib.CalConf(99, Model.SrOcr(), 0), 0, "0");
