    [Xunit.Fact]
    public static void TestTheTableIsSortedAndMonotoneInTheRawScore() {
        // Rows are [kind class raw-lo calibrated], sorted by kind, class, raw-lo; within one kind and class the raw-lo rises strictly
        // and the calibrated value never falls (isotonic), and a value is a confidence.
        int n = 19;
        int i = 1;
        emon.Testport.AssertThat(n > 0, "the table has a row (the identity table has one that no node matches)");
        while (i < n) {
            int k0 = Calibdata.CdRows[(i - 1) * 4 + 0];
            int c0 = Calibdata.CdRows[(i - 1) * 4 + 1];
            int k1 = Calibdata.CdRows[i * 4 + 0];
            int c1 = Calibdata.CdRows[i * 4 + 1];
            emon.Testport.AssertThat((k0 < k1) || ((k0 == k1) && (c0 <= c1)), "sorted by kind then class");
            if ((k0 == k1) && (c0 == c1)) {
                emon.Testport.AssertThat(Calibdata.CdRows[(i - 1) * 4 + 2] < Calibdata.CdRows[i * 4 + 2], "raw-lo rises within a kind and class");
                emon.Testport.AssertThat(Calibdata.CdRows[(i - 1) * 4 + 3] <= Calibdata.CdRows[i * 4 + 3], "calibrated never falls with the raw score");
            }
            emon.Testport.AssertThat((Calibdata.CdRows[i * 4 + 3] >= 0) && (Calibdata.CdRows[i * 4 + 3] <= 1000), "a calibrated value is 0..1000");
            i += 1;
        }
    }
    [Xunit.Fact]
    public static void TestEveryStepOfTheTableAnswersWithItsOwnValue() {
        // At a step's raw-lo (and one above it, if that is still below the next step) the lookup is the step's value,
        // for the class the row names (an `any` row is read through a class that has no row of its own: a class code
        // the table never names, 9, falls back to `any`).
        int n = 19;
        int i = 0;
        while (i < n) {
            if (Calibdata.CdRows[i * 4 + 1] == -1) {
                emon.Testport.AssertEqAt(Calib.CalLookup(Calibdata.CdRows[i * 4 + 0], 9, Calibdata.CdRows[i * 4 + 2]), Calibdata.CdRows[i * 4 + 3], "an any-row at its raw-lo", i);
            }
            i += 1;
        }
    }
    [Xunit.Fact]
    public static void TestTheLookupClampsAtBothEndsOfAStepFunction() {
        // Below a row's first step the first step's value; above the last the last's (no extrapolation).
        int n = 19;
        int i = 0;
        while (i < n) {
            if (Calibdata.CdRows[i * 4 + 1] == -1) {
                int kind = Calibdata.CdRows[i * 4 + 0];
                int firstV = -1;
                int lastV = -1;
                int j = 0;
                while (j < n) {
                    if ((Calibdata.CdRows[j * 4 + 0] == kind) && (Calibdata.CdRows[j * 4 + 1] == -1)) {
                        if (firstV < 0) {
                            firstV = Calibdata.CdRows[j * 4 + 3];
                        }
                        lastV = Calibdata.CdRows[j * 4 + 3];
                    }
                    j += 1;
                }
                emon.Testport.AssertEqAt(Calib.CalLookup(kind, 9, 0), firstV, "raw 0 takes the first step", i);
                emon.Testport.AssertEqAt(Calib.CalLookup(kind, 9, 1000), lastV, "raw 1000 takes the last step", i);
            }
            i += 1;
        }
    }
    [Xunit.Fact]
    public static void TestABlockFlaggedScriptUnreadIsWrittenAtItsRawScore() {
        // D1610: the map clamps at its first step, so a raw 100 on OCR text is written as the lowest confidence of text the engine READ; the engine's guess at a script it
        // cannot read keeps its raw score, and so do the inlines under it
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        int p1 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int t1 = Model.NodeNew(nodes, Model.NkText(), p1);
        int p2 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        Model.NodeAddSrc(nodes, p1, Model.SrOcr());
        Model.NodeSetConf(nodes, p1, 100);
        Model.NodeAddFlag(nodes, p1, Model.FlScriptUnread());
        Model.NodeAddSrc(nodes, t1, Model.SrOcr());
        Model.NodeSetConf(nodes, t1, 100);
        Model.NodeAddSrc(nodes, p2, Model.SrOcr());
        Model.NodeSetConf(nodes, p2, 100);
        int mapped = Calib.CalConf(Model.NkParagraph(), Model.SrOcr(), 100);
        int want = 100;
        if (mapped < 100) {
            want = mapped;
        }
        emon.Testport.AssertEq(Calib.CalNodeConf(nodes, p1), want, "the flagged block: its raw score, when the map would give more");
        emon.Testport.AssertThat(Calib.CalNodeConf(nodes, p1) <= 100, "never above it");
        emon.Testport.AssertThat(Calib.CalNodeConf(nodes, t1) <= 100, "the text under it too");
        emon.Testport.AssertEq(Calib.CalNodeConf(nodes, p2), mapped, "a block no one flagged is calibrated as it was");
    }
